-- ---------------------------------------------------------------------------
-- 2. Numeric helpers (ADR-003: money is rounded once, half to even)
-- ---------------------------------------------------------------------------
create or replace function public.div_round_half_even(p_num numeric, p_den numeric)
returns bigint
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_q numeric;
  v_r numeric;
begin
  if p_den is null or p_den = 0 or p_num is null then
    return null;
  end if;
  v_q := trunc(p_num / p_den);
  v_r := abs(p_num - v_q * p_den) * 2;
  if v_r > abs(p_den) or (v_r = abs(p_den) and mod(v_q, 2) <> 0) then
    v_q := v_q + sign(p_num) * sign(p_den);
  end if;
  return v_q::bigint;
end;
$$;
comment on function public.div_round_half_even(numeric, numeric) is 'Integer division rounded half to even (banker''s rounding), mirrors divRoundHalfEven() in src/lib/sim/money.ts.';

create or replace function public.order_value_cents(p_quantity bigint, p_price_e4 bigint)
returns bigint
language sql
immutable
set search_path = ''
as $$
  select public.div_round_half_even(p_quantity::numeric * p_price_e4, 100);
$$;
comment on function public.order_value_cents(bigint, bigint) is 'ADR-003: round_half_even(quantity x price_e4 / 100) in cents. The only place where a price turns into money.';

create or replace function public.apply_bps(p_amount bigint, p_bps numeric)
returns bigint
language sql
immutable
set search_path = ''
as $$
  select public.div_round_half_even(p_amount::numeric * p_bps, 10000);
$$;

-- Standard normal random number (Box-Muller). SQL may use random(); the
-- deterministic reference stays the TypeScript simulation.
create or replace function public.gauss_random()
returns double precision
language sql
volatile
set search_path = ''
as $$
  select sqrt(-2 * ln(1 - random())) * cos(2 * pi() * random());
$$;

-- Number inside an already loaded config document with a fallback.
create or replace function public.cfg_num(p_doc jsonb, p_path text[], p_fallback double precision)
returns double precision
language plpgsql
immutable
set search_path = ''
as $$
declare
  v jsonb;
begin
  v := p_doc #> p_path;
  if v is null or jsonb_typeof(v) <> 'number' then
    return p_fallback;
  end if;
  return (v #>> '{}')::double precision;
end;
$$;

create or replace function public.config_double(p_key text, p_path text[], p_fallback double precision)
returns double precision
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return public.cfg_num(public.config_jsonb(p_key), p_path, p_fallback);
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. API errors and caller identity
-- ---------------------------------------------------------------------------
create or replace function public.api_error(p_key text)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_code text;
begin
  v_code := case p_key
    when 'insufficient_funds'    then 'NX001'
    when 'rate_limited'          then 'NX004'
    when 'forbidden'             then 'NX006'
    when 'invalid_quantity'      then 'NX007'
    when 'invalid_price'         then 'NX007'
    when 'invalid_argument'      then 'NX007'
    when 'invalid_interval'      then 'NX007'
    when 'not_authenticated'     then 'NX010'
    when 'unknown_security'      then 'NX011'
    when 'not_tradable'          then 'NX012'
    when 'insufficient_position' then 'NX013'
    when 'order_not_found'       then 'NX014'
    when 'order_not_open'        then 'NX015'
    when 'market_paused'         then 'NX016'
    when 'nothing_to_claim'      then 'NX017'
    when 'locked'                then 'NX018'
    else 'NX007'
  end;
  raise exception using errcode = v_code, message = p_key;
end;
$$;
comment on function public.api_error(text) is 'Raises the API error <key> with its NX SQLSTATE. The client shows a text per key (error.message).';

create or replace function public.require_player()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null or not exists (select 1 from public.profiles p where p.id = v_uid) then
    perform public.api_error('not_authenticated');
  end if;
  return v_uid;
end;
$$;

-- Admin guard for the admin_* RPCs.
create or replace function public.require_admin()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is null then
    perform public.api_error('not_authenticated');
  end if;
  if not public.is_admin() then
    perform public.api_error('forbidden');
  end if;
  return (select auth.uid());
end;
$$;

-- Resolves a ticker (securities.ticker) or an index key (indices.key, e.g. NEXA30).
create or replace function public.resolve_security(p_ticker text)
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_t  text := upper(btrim(coalesce(p_ticker, '')));
  v_id uuid;
begin
  select s.id into v_id from public.securities s where s.ticker = v_t;
  if v_id is null then
    select i.security_id into v_id from public.indices i where upper(i.key) = v_t;
  end if;
  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. Game clock helpers (Europe/Berlin wall clock, ADR-006)
-- ---------------------------------------------------------------------------
-- Session: regular between time.marketOpenHour and time.marketCloseHour, else after_hours.
create or replace function public.market_session_at(p_at timestamptz)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_time  jsonb := coalesce(public.config_jsonb('time'), '{}'::jsonb);
  v_local timestamp := p_at at time zone 'Europe/Berlin';
  v_hour  double precision := extract(hour from v_local) + extract(minute from v_local) / 60.0;
begin
  if v_hour >= public.cfg_num(v_time, '{marketOpenHour}', 8)
     and v_hour < public.cfg_num(v_time, '{marketCloseHour}', 22) then
    return 'regular';
  end if;
  return 'after_hours';
end;
$$;

-- Start of the trading day: the most recent closing bell (22:00 Berlin) at or before p_at.
create or replace function public.trading_day_start(p_at timestamptz)
returns timestamptz
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_close double precision := public.config_double('time', '{marketCloseHour}', 22);
  v_off   interval := make_interval(secs => v_close * 3600);
begin
  return (((p_at at time zone 'Europe/Berlin') - v_off)::date + v_off) at time zone 'Europe/Berlin';
end;
$$;

-- Bucket start of the game quarter that contains p_at (08/14/20/02 Berlin, same rule as ensure_game_quarters).
create or replace function public.quarter_bucket_start(p_at timestamptz)
returns timestamptz
language sql
stable
set search_path = ''
as $$
  select ((date_trunc('hour', l) - make_interval(hours => (extract(hour from l)::integer % 6))) + interval '2 hours')
         at time zone 'Europe/Berlin'
    from (select (p_at at time zone 'Europe/Berlin') - interval '2 hours' as l) x;
$$;

-- Bucket start of the game year (= game day, 08:00 Berlin) that contains p_at.
create or replace function public.game_year_bucket_start(p_at timestamptz)
returns timestamptz
language sql
stable
set search_path = ''
as $$
  select (((p_at at time zone 'Europe/Berlin') - interval '8 hours')::date + interval '8 hours') at time zone 'Europe/Berlin';
$$;

-- ---------------------------------------------------------------------------
-- 5. Levels, unlocks and XP (mirrors src/lib/sim/progression.ts)
-- ---------------------------------------------------------------------------
create or replace function public.level_progress(p_xp bigint)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_prog  jsonb := coalesce(public.config_jsonb('progression'), '{}'::jsonb);
  v_base  double precision := public.cfg_num(v_prog, '{xpBase}', 100);
  v_exp   double precision := public.cfg_num(v_prog, '{xpExponent}', 1.5);
  v_max   integer := public.cfg_num(v_prog, '{maxLevel}', 50)::integer;
  v_level integer := 1;
  v_rem   bigint := greatest(coalesce(p_xp, 0), 0);
  v_need  bigint;
begin
  loop
    if v_level >= v_max then
      return jsonb_build_object('level', v_level, 'xp_into_level', v_rem, 'xp_for_next', 0);
    end if;
    v_need := round(v_base * power(v_level, v_exp))::bigint;
    if v_rem < v_need then
      return jsonb_build_object('level', v_level, 'xp_into_level', v_rem, 'xp_for_next', v_need);
    end if;
    v_rem := v_rem - v_need;
    v_level := v_level + 1;
  end loop;
end;
$$;
comment on function public.level_progress(bigint) is 'Level, XP inside the level and XP needed for the next level for a total XP (curve from game_config progression).';

create or replace function public.level_for_xp(p_xp bigint)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select (public.level_progress(p_xp) ->> 'level')::integer;
$$;

-- Level at which a feature unlocks: game_config progression.unlocks, then the unlocks table, else 1.
create or replace function public.unlock_level(p_key text)
returns integer
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_arr   jsonb := public.config_jsonb('progression', '{unlocks}');
  v_level integer;
begin
  if v_arr is not null and jsonb_typeof(v_arr) = 'array' then
    select min((u ->> 'level')::integer) into v_level
      from jsonb_array_elements(v_arr) u
     where u ->> 'key' = p_key and jsonb_typeof(u -> 'level') = 'number';
  end if;
  if v_level is null then
    select u.level into v_level from public.unlocks u where u.key = p_key;
  end if;
  return coalesce(v_level, 1);
end;
$$;

-- Grants XP once per dedupe key. Applies progression.xpMultiplier exactly
-- here (scaledXp), enforces the daily trade cap, keeps profiles.xp_total and
-- profiles.level in sync and grants the unlock rows of the new level.
-- Returns the XP credited (0 when capped or deduplicated).
create or replace function public.grant_xp(
  p_player     uuid,
  p_source     public.xp_source,
  p_base_xp    integer,
  p_dedupe_key text default null,
  p_ref_type   text default null,
  p_ref_id     uuid default null
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_prog   jsonb := coalesce(public.config_jsonb('progression'), '{}'::jsonb);
  v_mult   double precision := public.cfg_num(v_prog, '{xpMultiplier}', 2);
  v_day    date := (public.game_now() at time zone 'Europe/Berlin')::date;
  v_amount integer;
  v_cap    integer;
  v_count  integer;
  v_id     bigint;
  v_total  bigint;
  v_level  integer;
begin
  if p_player is null or p_base_xp is null or p_base_xp <= 0 then
    return 0;
  end if;
  v_amount := greatest(0, round(p_base_xp * v_mult))::integer;
  if v_amount <= 0 then
    return 0;
  end if;

  if p_source = 'trade' then
    v_cap := public.cfg_num(v_prog, '{xpSources,trade,maxTradesPerDay}', 30)::integer;
    select c.event_count into v_count
      from public.xp_daily_counters c
     where c.player_id = p_player and c.game_day = v_day and c.source = p_source
       for update;
    if coalesce(v_count, 0) >= v_cap then
      return 0;
    end if;
  end if;

  insert into public.xp_events (player_id, source, amount, multiplier_bps, ref_type, ref_id, dedupe_key, game_day)
  values (p_player, p_source, v_amount, round(v_mult * 10000)::integer, p_ref_type, p_ref_id, p_dedupe_key, v_day)
  on conflict (player_id, dedupe_key) do nothing
  returning id into v_id;
  if v_id is null then
    return 0;
  end if;

  insert into public.xp_daily_counters as c (player_id, game_day, source, event_count, xp_sum)
  values (p_player, v_day, p_source, 1, v_amount)
  on conflict (player_id, game_day, source)
  do update set event_count = c.event_count + 1, xp_sum = c.xp_sum + excluded.xp_sum;

  update public.profiles p set xp_total = p.xp_total + v_amount where p.id = p_player
  returning p.xp_total into v_total;
  v_level := public.level_for_xp(v_total);
  update public.profiles p set level = v_level where p.id = p_player and p.level <> v_level;
  update public.xp_events e set level_after = v_level where e.id = v_id;

  insert into public.player_unlocks (player_id, unlock_key)
  select p_player, u.key from public.unlocks u where u.level <= v_level
  on conflict do nothing;

  return v_amount;
end;
$$;
comment on function public.grant_xp(uuid, public.xp_source, integer, text, text, uuid) is 'Internal: credits XP (x progression.xpMultiplier) once per dedupe key, daily trade cap, level and unlocks. Returns the XP credited.';

-- ---------------------------------------------------------------------------
-- 6. Sign-up: same as migration 1300, plus a vault that already holds
--    economy.vaultInitialHours of basic income (the tutorial claims it).
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_meta            jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_code            text  := nullif(upper(btrim(coalesce(v_meta ->> 'invite_code', ''))), '');
  v_invite_required boolean := public.config_boolean('auth', '{inviteRequired}', true);
  v_age_required    boolean := public.config_boolean('auth', '{ageConfirmationRequired}', true);
  v_age_confirmed   boolean := lower(coalesce(v_meta ->> 'age_confirmed', 'false')) in ('true', '1', 'yes');
  v_start_cents     bigint  := greatest(public.config_bigint('economy', '{startingCapitalCents}', 1000000), 0);
  v_vault_hours     double precision := greatest(0, least(
                        public.config_double('economy', '{vaultInitialHours}', 2),
                        public.config_double('economy', '{vaultCapHours}', 8)));
  v_invite          public.invite_codes;
  v_base            text;
  v_nickname        text;
  v_attempt         integer := 0;
  v_cash_account    uuid;
begin
  -- 18+ confirmation ---------------------------------------------------------
  if v_age_required and not v_age_confirmed then
    raise exception 'age confirmation (18+) is required' using errcode = 'NX007';
  end if;

  -- invite code ---------------------------------------------------------------
  if v_code is not null then
    select i.* into v_invite from public.invite_codes i where i.code = v_code for update;
    if not found
       or not v_invite.is_active
       or (v_invite.expires_at is not null and v_invite.expires_at <= now())
       or v_invite.used_count >= v_invite.max_uses then
      if v_invite_required then
        raise exception 'invite code is invalid, expired or used up' using errcode = 'NX005';
      end if;
      v_code := null;
    end if;
  elsif v_invite_required then
    raise exception 'an invite code is required' using errcode = 'NX005';
  end if;

  -- nickname -------------------------------------------------------------------
  v_base := left(regexp_replace(coalesce(v_meta ->> 'nickname', ''), '[^A-Za-z0-9_]', '', 'g'), 20);
  if length(v_base) < 3 then
    v_base := 'Trader';
    v_nickname := v_base || (floor(random() * 90000) + 10000)::integer::text;
  else
    v_nickname := v_base;
  end if;
  while exists (select 1 from public.profiles p where lower(p.nickname) = lower(v_nickname)) loop
    v_attempt := v_attempt + 1;
    if v_attempt > 20 then
      raise exception 'could not generate a unique nickname' using errcode = 'NX007';
    end if;
    v_nickname := left(v_base, 15) || (floor(random() * 90000) + 10000)::integer::text;
  end loop;

  -- player rows ----------------------------------------------------------------
  insert into public.profiles (id, nickname) values (new.id, v_nickname);
  insert into public.player_private (player_id, age_confirmed_at)
  values (new.id, case when v_age_confirmed then now() end);
  insert into public.player_settings (player_id) values (new.id);
  insert into public.vaults (player_id, accrual_started_at)
  values (new.id, public.game_now() - make_interval(secs => v_vault_hours * 3600));
  insert into public.login_streaks (player_id) values (new.id);

  insert into public.player_unlocks (player_id, unlock_key)
  select new.id, u.key from public.unlocks u where u.level <= 1;

  insert into public.notification_preferences (player_id, type_key, in_app_enabled, push_enabled)
  select new.id, t.key, t.default_in_app, t.default_push from public.notification_types t;

  -- ledger: cash + reserve account, starting capital from the mint -------------
  insert into public.ledger_accounts (kind, owner_player_id, label)
  values ('player_cash', new.id, 'Cash')
  returning id into v_cash_account;
  insert into public.ledger_accounts (kind, owner_player_id, label)
  values ('player_reserve', new.id, 'Reserved (orders, subscriptions, margin)');

  if v_start_cents > 0 then
    perform public.ledger_transfer(
      public.ledger_system_account('mint'),
      v_cash_account,
      v_start_cents,
      'starting_capital',
      'Starting capital',
      'profile',
      new.id,
      'starting_capital:' || new.id::text,
      new.id
    );
  end if;

  -- consume the invite ---------------------------------------------------------
  if v_code is not null then
    update public.invite_codes set used_count = used_count + 1 where code = v_code;
    insert into public.invite_code_redemptions (code, player_id) values (v_code, new.id);
  end if;

  return new;
end;
$$;
comment on function public.handle_new_user() is 'Trigger on auth.users: validates invite/age, creates profile, settings, vault (pre-filled with economy.vaultInitialHours), ledger accounts, starting capital, notification defaults.';

-- ---------------------------------------------------------------------------
-- 7. Privileges: everything in this file is internal
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.div_round_half_even(numeric, numeric)', 'public.order_value_cents(bigint, bigint)',
    'public.apply_bps(bigint, numeric)', 'public.gauss_random()', 'public.cfg_num(jsonb, text[], double precision)',
    'public.config_double(text, text[], double precision)', 'public.api_error(text)', 'public.require_player()',
    'public.require_admin()', 'public.resolve_security(text)', 'public.market_session_at(timestamptz)',
    'public.trading_day_start(timestamptz)', 'public.quarter_bucket_start(timestamptz)',
    'public.game_year_bucket_start(timestamptz)', 'public.level_progress(bigint)', 'public.level_for_xp(bigint)',
    'public.unlock_level(text)', 'public.grant_xp(uuid, public.xp_source, integer, text, text, uuid)',
    'public.handle_new_user()'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end;
$$;
-- ===== idempotent copy of migrations/20261111000200_m1_trading.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M1 · 0200 · Trading: fills, place_order, cancel_order, vault,
--                    tutorial
-- =============================================================================
-- Execution model (docs/SIMULATION.md 6-8, ADR-005, ADR-025):
--   * every player order trades against the market maker; a market order
--     walks the synthetic book from the touch price (ask for buys, bid for
--     sells). With linear impact the average price is
--         touch x (1 +- a x (pending + q / 2)),   a = impactBpsPerDepth / 1e4 / depth
--     where "pending" is the same-direction player flow not yet absorbed by
--     the next market tick (so splitting an order inside one tick does not help)
--   * the net flow is stored in security_sim_state.pending_player_flow and
--     moves the price in the next tick (immediate share), the market maker
--     hedges the rest over the following ticks
--   * fee: trading.orderFeeCents once per order (first fill)
--   * tax: trading.capitalGainsTaxBps on realised gains after fees, FIFO lots,
--     loss pot in player_private.tax_loss_pot_cents (never refunded)
--   * lock order (deadlock free): player ledger accounts (id order) ->
--     position / order / player rows -> system ledger accounts (ledger_post)
--     -> security_quotes / security_sim_state
-- =============================================================================

-- Market depth in shares (one depth moves the price by impactBpsPerDepth).
create or replace function public.security_depth(p_security_id uuid, p_regular boolean)
returns double precision
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_kind   public.security_kind;
  v_shares bigint;
  v_liq    bigint;
  v_base   double precision;
  v_factor double precision := 1;
begin
  select s.kind, c.shares_outstanding, st.liquidity_shares
    into v_kind, v_shares, v_liq
    from public.securities s
    left join public.companies c on c.id = s.company_id
    left join public.security_sim_state st on st.security_id = s.id
   where s.id = p_security_id;
  if v_kind = 'stock' and v_shares is not null then
    v_base := v_shares * public.config_double('trading', '{priceImpact,depthFreeFloatFraction}', 0.002);
  else
    v_base := coalesce(v_liq, 100000);
  end if;
  if not p_regular then
    v_factor := public.config_double('time', '{afterHours,liquidityMultiplier}', 0.25);
  end if;
  return greatest(1, v_base * v_factor);
end;
$$;

-- ---------------------------------------------------------------------------
-- execute_fill: books ONE fill of an order against the market maker.
--   p_resting  true = a resting limit order filled by the tick (buys pay from
--              the reserve account, sells deliver reserved shares)
--   p_system   true = system order (bond redemption): no fee, no XP
-- ---------------------------------------------------------------------------
create or replace function public.execute_fill(
  p_order_id uuid,
  p_quantity bigint,
  p_price_e4 bigint,
  p_resting  boolean default false,
  p_system   boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  o            public.orders;
  v_trading    jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  v_prog       jsonb := coalesce(public.config_jsonb('progression'), '{}'::jsonb);
  v_now        timestamptz := public.game_now();
  v_cash       uuid;
  v_reserve    uuid;
  v_gross      bigint;
  v_fee        bigint := 0;
  v_tax        bigint := 0;
  v_pnl        bigint;
  v_cost       bigint := 0;
  v_release    bigint := 0;
  v_cash_delta bigint;
  v_balance    bigint;
  v_pos        public.positions;
  v_basis_new  bigint;
  v_avg_new    bigint;
  v_trade_id   uuid := gen_random_uuid();
  v_tx         uuid;
  v_xp         integer := 0;
  v_wash       boolean := false;
  v_pot        bigint;
  v_offset     bigint;
  v_left       bigint;
  v_take       bigint;
  v_entries    jsonb;
  v_tick_seq   bigint;
  v_year       integer;
  lot          record;
begin
  select * into o from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'order % does not exist', p_order_id using errcode = 'NX007';
  end if;
  if p_quantity is null or p_quantity <= 0 or p_quantity > o.quantity - o.filled_quantity then
    raise exception 'invalid fill quantity % for order %', p_quantity, p_order_id using errcode = 'NX007';
  end if;
  if p_price_e4 is null or p_price_e4 <= 0 then
    raise exception 'invalid fill price %', p_price_e4 using errcode = 'NX007';
  end if;

  v_gross := public.order_value_cents(p_quantity, p_price_e4);
  if o.fee_cents = 0 and not p_system then
    v_fee := greatest(0, public.cfg_num(v_trading, '{orderFeeCents}', 100))::bigint;
  end if;
  v_cash    := public.ledger_player_account(o.player_id, 'player_cash');
  v_reserve := public.ledger_player_account(o.player_id, 'player_reserve');
  select a.balance_cents into v_balance from public.ledger_accounts a where a.id = v_cash;

  select * into v_pos
    from public.positions p
   where p.player_id = o.player_id and p.security_id = o.security_id
     and p.side = 'long' and p.leverage = 1 and p.status = 'open'
     for update;

  if o.side = 'buy' then
    if p_resting then
      v_release := o.reserved_cents;
    end if;
    v_cash_delta := v_release - v_gross - v_fee;
    if v_balance + v_cash_delta < 0 then
      perform public.api_error('insufficient_funds');
    end if;
    if v_pos.id is null then
      insert into public.positions (player_id, security_id, quantity, avg_entry_price_e4, cost_basis_cents, opened_at)
      values (o.player_id, o.security_id, 0, p_price_e4, 0, v_now)
      returning * into v_pos;
    end if;
  else
    if v_pos.id is null
       or v_pos.quantity < p_quantity
       or (not p_resting and v_pos.quantity - v_pos.reserved_quantity < p_quantity)
       or (p_resting and v_pos.reserved_quantity < p_quantity) then
      perform public.api_error('insufficient_position');
    end if;
    -- FIFO lots
    v_left := p_quantity;
    for lot in
      select l.id, l.quantity_open
        from public.position_lots l
       where l.position_id = v_pos.id and l.quantity_open > 0
       order by l.acquired_at, l.id
         for update
    loop
      exit when v_left = 0;
      v_take := least(v_left, lot.quantity_open);
      update public.position_lots
         set quantity_open = quantity_open - v_take,
             closed_at = case when quantity_open - v_take = 0 then v_now else closed_at end
       where id = lot.id;
      v_left := v_left - v_take;
    end loop;
    select coalesce(sum(public.order_value_cents(l.quantity_open, l.price_e4)), 0)::bigint
      into v_basis_new
      from public.position_lots l where l.position_id = v_pos.id and l.quantity_open > 0;
    if v_left > 0 then
      -- position without lot history (should not happen): value the rest at the average entry
      v_cost := v_pos.cost_basis_cents - v_basis_new + public.order_value_cents(v_left, v_pos.avg_entry_price_e4);
    else
      v_cost := v_pos.cost_basis_cents - v_basis_new;
    end if;
    v_cost := greatest(v_cost, 0);

    v_pnl := v_gross - v_fee - v_cost;
    select pp.tax_loss_pot_cents into v_pot
      from public.player_private pp where pp.player_id = o.player_id for update;
    v_pot := coalesce(v_pot, 0);
    if v_pnl <= 0 then
      v_pot := v_pot - v_pnl;
    else
      v_offset := least(v_pnl, v_pot);
      v_tax := public.apply_bps(v_pnl - v_offset, public.cfg_num(v_trading, '{capitalGainsTaxBps}', 2500)::numeric);
      v_pot := v_pot - v_offset;
    end if;
    update public.player_private set tax_loss_pot_cents = v_pot where player_id = o.player_id;

    v_cash_delta := v_gross - v_fee - v_tax;
    if v_balance + v_cash_delta < 0 then
      perform public.api_error('insufficient_funds');
    end if;
    v_wash := exists (
      select 1 from public.trades t
       where t.player_id = o.player_id and t.security_id = o.security_id and t.side = 'buy'
         and t.executed_at > v_now - make_interval(secs => public.cfg_num(v_trading, '{washTradeWindowSeconds}', 600)));
  end if;

  -- ledger: one balanced transaction per fill
  select coalesce(jsonb_agg(jsonb_build_object('account_id', e.account_id, 'amount_cents', e.amount)), '[]'::jsonb)
    into v_entries
    from (values
      (v_cash,                                    v_cash_delta),
      (v_reserve,                                 -v_release),
      (public.ledger_system_account('market'),    case when o.side = 'buy' then v_gross else -v_gross end),
      (public.ledger_system_account('fees'),      v_fee),
      (public.ledger_system_account('taxes'),     v_tax)
    ) as e(account_id, amount)
   where e.amount <> 0;
  if jsonb_array_length(v_entries) >= 2 then
    v_tx := public.ledger_post(
      case when p_system then 'bond_redemption'::public.ledger_tx_kind
           when o.side = 'buy' then 'trade_buy'::public.ledger_tx_kind
           else 'trade_sell'::public.ledger_tx_kind end,
      v_entries,
      case when o.side = 'buy' then 'Kauf ' else 'Verkauf ' end || p_quantity || ' Stück',
      'order', o.id, 'fill:' || v_trade_id::text, o.player_id,
      jsonb_build_object('quantity', p_quantity, 'price_e4', p_price_e4, 'trade_id', v_trade_id));
  end if;

  -- XP: one trade XP per order (progression.xpSources.trade), not below the
  -- minimum order value, not for closing a position opened inside the wash-trade window
  if not p_system and not v_wash
     and v_gross >= public.cfg_num(v_prog, '{xpSources,trade,minOrderValueCents}', 10000) then
    v_xp := public.grant_xp(o.player_id, 'trade', public.cfg_num(v_prog, '{xpSources,trade,xp}', 10)::integer,
                            'trade:' || o.id::text, 'trade', v_trade_id);
  end if;

  select r.tick_seq into v_tick_seq from public.sim_runtime r where r.id;
  insert into public.trades (
    id, order_id, player_id, security_id, position_id, side, quantity, price_e4, gross_cents, fee_cents,
    tax_cents, realized_pnl_cents, counterparty, ledger_transaction_id, tick_seq, is_wash_trade, xp_awarded, executed_at)
  values (
    v_trade_id, o.id, o.player_id, o.security_id, v_pos.id, o.side, p_quantity, p_price_e4, v_gross, v_fee,
    v_tax, case when o.side = 'sell' then v_pnl end,
    case when p_system then 'issuer'::public.trade_counterparty else 'market_maker'::public.trade_counterparty end,
    v_tx, v_tick_seq, v_wash, v_xp, v_now);

  -- position and lots
  if o.side = 'buy' then
    insert into public.position_lots (position_id, player_id, security_id, trade_id, quantity_initial, quantity_open, price_e4, acquired_at)
    values (v_pos.id, o.player_id, o.security_id, v_trade_id, p_quantity, p_quantity, p_price_e4, v_now);
    select coalesce(sum(public.order_value_cents(l.quantity_open, l.price_e4)), 0)::bigint,
           coalesce(public.div_round_half_even(sum(l.quantity_open::numeric * l.price_e4), sum(l.quantity_open)), p_price_e4)
      into v_basis_new, v_avg_new
      from public.position_lots l where l.position_id = v_pos.id and l.quantity_open > 0;
    update public.positions
       set quantity = quantity + p_quantity,
           cost_basis_cents = v_basis_new,
           avg_entry_price_e4 = v_avg_new
     where id = v_pos.id;
  else
    select coalesce(public.div_round_half_even(sum(l.quantity_open::numeric * l.price_e4), sum(l.quantity_open)), 0)
      into v_avg_new
      from public.position_lots l where l.position_id = v_pos.id and l.quantity_open > 0;
    update public.positions
       set quantity = quantity - p_quantity,
           reserved_quantity = case when p_resting then reserved_quantity - p_quantity else reserved_quantity end,
           cost_basis_cents = v_basis_new,
           avg_entry_price_e4 = case when quantity - p_quantity = 0 then avg_entry_price_e4 else v_avg_new end,
           realized_pnl_cents = realized_pnl_cents + v_pnl,
           status = case when quantity - p_quantity = 0 then 'closed'::public.position_status else status end,
           closed_at = case when quantity - p_quantity = 0 then v_now else closed_at end
     where id = v_pos.id;

    v_year := coalesce((select q.game_year from public.current_game_quarter() q), 0);
    insert into public.player_tax_years as t (player_id, game_year, realized_gains_cents, realized_losses_cents, tax_paid_cents)
    values (o.player_id, v_year, greatest(v_pnl, 0), greatest(-v_pnl, 0), v_tax)
    on conflict (player_id, game_year) do update
      set realized_gains_cents  = t.realized_gains_cents + excluded.realized_gains_cents,
          realized_losses_cents = t.realized_losses_cents + excluded.realized_losses_cents,
          tax_paid_cents        = t.tax_paid_cents + excluded.tax_paid_cents,
          updated_at            = now();
  end if;

  update public.orders
     set filled_quantity    = filled_quantity + p_quantity,
         avg_fill_price_e4  = public.div_round_half_even(
                                coalesce(avg_fill_price_e4, 0)::numeric * filled_quantity + p_price_e4::numeric * p_quantity,
                                filled_quantity + p_quantity),
         fee_cents          = fee_cents + v_fee,
         reserved_cents     = case when p_resting and side = 'buy' then 0 else reserved_cents end,
         reserved_quantity  = case when p_resting and side = 'sell' then reserved_quantity - p_quantity else reserved_quantity end,
         status             = case when filled_quantity + p_quantity >= quantity then 'filled'::public.order_status
                                   else 'partially_filled'::public.order_status end,
         filled_at          = case when filled_quantity + p_quantity >= quantity then v_now else filled_at end
   where id = o.id;

  -- market data: volume now, price effect in the next tick (player flow)
  update public.security_quotes
     set day_volume = day_volume + p_quantity,
         day_turnover_cents = day_turnover_cents + v_gross
   where security_id = o.security_id;
  if not p_system then
    update public.security_sim_state
       set pending_player_flow = pending_player_flow + case when o.side = 'buy' then p_quantity else -p_quantity end
     where security_id = o.security_id;
  end if;

  return jsonb_build_object(
    'trade_id', v_trade_id, 'quantity', p_quantity, 'price_e4', p_price_e4, 'gross_cents', v_gross,
    'fee_cents', v_fee, 'tax_cents', v_tax, 'realized_pnl_cents', case when o.side = 'sell' then v_pnl end,
    'xp_awarded', v_xp, 'wash_trade', v_wash);
end;
$$;
comment on function public.execute_fill(uuid, bigint, bigint, boolean, boolean) is 'Internal: books one fill (ledger, position, FIFO lots, fee, tax with loss pot, trade XP, player flow). Caller holds the player''s account locks.';

-- Cancels an open order and releases its reservation. Caller holds the account locks.
create or replace function public.cancel_order_internal(p_order_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  o public.orders;
begin
  select * into o from public.orders where id = p_order_id for update;
  if not found then
    perform public.api_error('order_not_found');
  end if;
  if o.status not in ('pending', 'open', 'partially_filled') then
    perform public.api_error('order_not_open');
  end if;
  if o.side = 'buy' and o.reserved_cents > 0 then
    perform public.ledger_transfer(
      public.ledger_player_account(o.player_id, 'player_reserve'),
      public.ledger_player_account(o.player_id, 'player_cash'),
      o.reserved_cents, 'order_release', 'Freigabe Limit-Order', 'order', o.id,
      'release:' || o.id::text, o.player_id);
  end if;
  if o.side = 'sell' and o.reserved_quantity > 0 then
    update public.positions p
       set reserved_quantity = greatest(0, p.reserved_quantity - o.reserved_quantity)
     where p.player_id = o.player_id and p.security_id = o.security_id
       and p.side = 'long' and p.leverage = 1 and p.status = 'open';
  end if;
  update public.orders
     set status = 'cancelled', cancelled_at = now(), reserved_cents = 0, reserved_quantity = 0
   where id = o.id;
  return jsonb_build_object('order_id', o.id, 'status', 'cancelled');
end;
$$;

-- Locks the caller's ledger accounts (cash, reserve) in id order and returns the cash balance.
create or replace function public.lock_player_accounts(p_player uuid)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cash bigint;
begin
  perform 1 from public.ledger_accounts a where a.owner_player_id = p_player order by a.id for update;
  select a.balance_cents into v_cash from public.ledger_accounts a
   where a.owner_player_id = p_player and a.kind = 'player_cash';
  return coalesce(v_cash, 0);
end;
$$;

-- ---------------------------------------------------------------------------
-- place_order (RPC)
-- ---------------------------------------------------------------------------
create or replace function public.place_order(
  p_request_id     uuid,
  p_ticker         text,
  p_side           text,
  p_type           text,
  p_quantity       bigint,
  p_limit_price_e4 bigint default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player     uuid;
  v_replay     jsonb;
  v_trading    jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  v_abuse      jsonb := coalesce(public.config_jsonb('abuse'), '{}'::jsonb);
  v_side       public.order_side;
  v_type       public.order_type;
  v_limit      bigint;
  s            public.securities;
  v_level      integer;
  v_cash       bigint;
  v_bid        bigint;
  v_ask        bigint;
  v_pending    bigint;
  v_regular    boolean;
  v_depth      double precision;
  v_a          double precision;
  v_pos        double precision;
  v_touch      bigint;
  v_fill_qty   bigint := 0;
  v_fill_price bigint;
  v_rest       bigint;
  v_fee        bigint;
  v_need       bigint;
  v_reserve    bigint := 0;
  v_avail      bigint;
  v_order_id   uuid := gen_random_uuid();
  v_fill       jsonb;
  o            public.orders;
  v_prof       public.profiles;
  v_min_price  bigint;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'place_order');
  if v_replay is not null then
    return v_replay;
  end if;

  -- inputs -------------------------------------------------------------------
  if lower(coalesce(p_side, '')) not in ('buy', 'sell') or lower(coalesce(p_type, '')) not in ('market', 'limit') then
    perform public.api_error('invalid_argument');
  end if;
  v_side := lower(p_side)::public.order_side;
  v_type := lower(p_type)::public.order_type;
  if p_quantity is null or p_quantity < 1
     or p_quantity > public.cfg_num(v_trading, '{maxOrderQuantity}', 100000) then
    perform public.api_error('invalid_quantity');
  end if;
  if v_type = 'limit' then
    if p_limit_price_e4 is null or p_limit_price_e4 < 1 or p_limit_price_e4 > 100000000000 then
      perform public.api_error('invalid_price');
    end if;
    v_limit := p_limit_price_e4;
  end if;

  select * into s from public.securities where id = public.resolve_security(p_ticker);
  if s.id is null then
    perform public.api_error('unknown_security');
  end if;
  if s.kind not in ('stock', 'bond') or s.status <> 'listed' or not s.is_tradable then
    perform public.api_error('not_tradable');
  end if;
  if (select r.is_paused from public.sim_runtime r where r.id) then
    perform public.api_error('market_paused');
  end if;

  select p.level into v_level from public.profiles p where p.id = v_player;
  if v_type = 'limit' and v_level < public.unlock_level('limit_orders') then
    perform public.api_error('locked');
  end if;
  if s.kind = 'bond' and v_level < public.unlock_level('bonds') then
    perform public.api_error('locked');
  end if;

  if not public.rate_limit_hit(v_player, 'place_order',
           greatest(1, public.cfg_num(v_abuse, '{rateLimits,ordersPerMinute}', 20))::integer, 60)
     or not public.rate_limit_hit(v_player, 'place_order_day',
           greatest(1, public.cfg_num(v_abuse, '{rateLimits,ordersPerDay}', 500))::integer, 86400) then
    perform public.api_error('rate_limited');
  end if;

  -- locks, quote ---------------------------------------------------------------
  v_cash := public.lock_player_accounts(v_player);
  select q.bid_e4, q.ask_e4 into v_bid, v_ask from public.security_quotes q where q.security_id = s.id;
  select st.pending_player_flow into v_pending from public.security_sim_state st where st.security_id = s.id;
  if v_bid is null or v_ask is null then
    perform public.api_error('not_tradable');
  end if;
  v_pending   := coalesce(v_pending, 0);
  v_regular   := public.market_session_at(public.game_now()) = 'regular';
  v_depth     := public.security_depth(s.id, v_regular);
  v_a         := public.cfg_num(v_trading, '{priceImpact,impactBpsPerDepth}', 100) / 10000.0 / v_depth;
  v_fee       := greatest(0, public.cfg_num(v_trading, '{orderFeeCents}', 100))::bigint;
  v_min_price := greatest(1, public.cfg_num(v_trading, '{minPriceE4}', 1))::bigint;

  if v_side = 'buy' then
    v_touch := v_ask;
    v_pos := greatest(v_pending, 0);
  else
    v_touch := v_bid;
    v_pos := greatest(-v_pending, 0);
  end if;

  -- how much executes now --------------------------------------------------------
  if v_type = 'market' then
    v_fill_qty := p_quantity;
  elsif v_side = 'buy' and v_touch <= v_limit then
    if v_touch * (1 + v_a * (v_pos + p_quantity)) <= v_limit then
      v_fill_qty := p_quantity;
    else
      v_fill_qty := greatest(0, least(p_quantity, floor((v_limit::double precision / v_touch - 1) / v_a - v_pos)::bigint));
    end if;
  elsif v_side = 'sell' and v_touch >= v_limit then
    if v_touch * (1 - v_a * (v_pos + p_quantity)) >= v_limit then
      v_fill_qty := p_quantity;
    else
      v_fill_qty := greatest(0, least(p_quantity, floor((1 - v_limit::double precision / v_touch) / v_a - v_pos)::bigint));
    end if;
  end if;

  if v_fill_qty > 0 then
    if v_side = 'buy' then
      v_fill_price := round(v_touch * (1 + v_a * (v_pos + v_fill_qty / 2.0)))::bigint;
      if v_type = 'limit' then
        v_fill_price := least(v_fill_price, v_limit);
      end if;
    else
      v_fill_price := greatest(v_min_price, round(v_touch * (1 - v_a * (v_pos + v_fill_qty / 2.0)))::bigint);
      if v_type = 'limit' then
        v_fill_price := greatest(v_fill_price, v_limit);
      end if;
    end if;
  end if;
  v_rest := p_quantity - v_fill_qty;

  -- funds / shares ---------------------------------------------------------------
  if v_side = 'sell' then
    select p.quantity - p.reserved_quantity into v_avail
      from public.positions p
     where p.player_id = v_player and p.security_id = s.id and p.side = 'long' and p.leverage = 1 and p.status = 'open'
       for update;
    if coalesce(v_avail, 0) < p_quantity then
      perform public.api_error('insufficient_position');
    end if;
  else
    v_need := 0;
    if v_fill_qty > 0 then
      v_need := public.order_value_cents(v_fill_qty, v_fill_price) + v_fee;
    end if;
    if v_rest > 0 then
      v_need := v_need + public.order_value_cents(v_rest, v_limit) + case when v_fill_qty > 0 then 0 else v_fee end;
    end if;
    if v_need > v_cash then
      perform public.api_error('insufficient_funds');
    end if;
  end if;

  -- order, fill, reservation ---------------------------------------------------------
  insert into public.orders (id, player_id, security_id, request_id, side, type, quantity, limit_price_e4, status)
  values (v_order_id, v_player, s.id, p_request_id, v_side, v_type, p_quantity, v_limit, 'pending');

  if v_fill_qty > 0 then
    v_fill := public.execute_fill(v_order_id, v_fill_qty, v_fill_price, false, false);
  end if;

  if v_rest > 0 then
    select * into o from public.orders where id = v_order_id;
    if v_side = 'buy' then
      v_reserve := public.order_value_cents(v_rest, v_limit) + case when o.fee_cents = 0 then v_fee else 0 end;
      if v_reserve > 0 then
        perform public.ledger_transfer(
          public.ledger_player_account(v_player, 'player_cash'),
          public.ledger_player_account(v_player, 'player_reserve'),
          v_reserve, 'order_reserve', 'Reservierung Limit-Order', 'order', v_order_id,
          'reserve:' || v_order_id::text, v_player);
      end if;
      update public.orders set reserved_cents = v_reserve where id = v_order_id;
    else
      update public.positions p
         set reserved_quantity = p.reserved_quantity + v_rest
       where p.player_id = v_player and p.security_id = s.id and p.side = 'long' and p.leverage = 1 and p.status = 'open';
      update public.orders set reserved_quantity = v_rest where id = v_order_id;
    end if;
    update public.orders
       set status = case when v_fill_qty > 0 then 'partially_filled'::public.order_status else 'open'::public.order_status end
     where id = v_order_id;
  end if;

  select * into o from public.orders where id = v_order_id;
  select * into v_prof from public.profiles where id = v_player;
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'order_id',           o.id,
    'status',             o.status,
    'filled_quantity',    o.filled_quantity,
    'avg_price_e4',       o.avg_fill_price_e4,
    'gross_cents',        coalesce((v_fill ->> 'gross_cents')::bigint, 0),
    'fee_cents',          o.fee_cents,
    'tax_cents',          coalesce((v_fill ->> 'tax_cents')::bigint, 0),
    'realized_pnl_cents', (v_fill ->> 'realized_pnl_cents')::bigint,
    'cash_cents',         (select a.balance_cents from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash'),
    'reserved_cents',     o.reserved_cents,
    'xp_awarded',         coalesce((v_fill ->> 'xp_awarded')::integer, 0),
    'level',              v_prof.level,
    'xp_total',           v_prof.xp_total,
    'ticker',             s.ticker,
    'side',               o.side,
    'type',               o.type,
    'quantity',           o.quantity,
    'limit_price_e4',     o.limit_price_e4));
end;
$$;
comment on function public.place_order(uuid, text, text, text, bigint, bigint) is 'RPC: market or limit order (stocks and bonds), idempotent per request_id. See docs/DATA_MODEL.md, Nachtrag M1.';

-- ---------------------------------------------------------------------------
-- cancel_order (RPC)
-- ---------------------------------------------------------------------------
create or replace function public.cancel_order(p_request_id uuid, p_order_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_owner  uuid;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'cancel_order');
  if v_replay is not null then
    return v_replay;
  end if;
  if not public.rate_limit_hit(v_player, 'player_action',
           greatest(1, public.config_double('abuse', '{rateLimits,actionsPerMinute}', 60))::integer, 60) then
    perform public.api_error('rate_limited');
  end if;
  perform public.lock_player_accounts(v_player);
  select o.player_id into v_owner from public.orders o where o.id = p_order_id;
  if v_owner is null or v_owner <> v_player then
    perform public.api_error('order_not_found');
  end if;
  return public.request_complete(v_player, p_request_id, public.cancel_order_internal(p_order_id));
end;
$$;

-- ---------------------------------------------------------------------------
-- Vault (basic income) and tutorial
-- ---------------------------------------------------------------------------
create or replace function public.vault_status(p_player uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_rate    bigint := greatest(0, public.config_bigint('economy', '{basicIncomeCentsPerHour}', 10000));
  v_hours   double precision := greatest(0, public.config_double('economy', '{vaultCapHours}', 8));
  v_now     timestamptz := public.game_now();
  v         public.vaults;
  v_ms      double precision;
begin
  select * into v from public.vaults where player_id = p_player;
  if not found then
    return null;
  end if;
  v_ms := least(greatest(0, extract(epoch from (v_now - v.accrual_started_at)) * 1000), v_hours * 3600000);
  return jsonb_build_object(
    'accrued_cents',       floor(v_rate * v_ms / 3600000)::bigint,
    'cap_cents',           round(v_rate * v_hours)::bigint,
    'rate_cents_per_hour', v_rate,
    'last_claimed_at',     v.last_claimed_at,
    'full_at',             v.accrual_started_at + make_interval(secs => v_hours * 3600),
    'server_time',         v_now,
    'accrued_seconds',     floor(v_ms / 1000)::bigint);
end;
$$;

create or replace function public.claim_vault(p_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player  uuid;
  v_replay  jsonb;
  v_status  jsonb;
  v_amount  bigint;
  v_now     timestamptz := public.game_now();
  v_tx      uuid;
  v_total   integer;
  v_counted integer;
  v_hours   double precision := greatest(0, public.config_double('economy', '{vaultCapHours}', 8));
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'claim_vault');
  if v_replay is not null then
    return v_replay;
  end if;
  if not public.rate_limit_hit(v_player, 'player_action',
           greatest(1, public.config_double('abuse', '{rateLimits,actionsPerMinute}', 60))::integer, 60) then
    perform public.api_error('rate_limited');
  end if;
  perform public.lock_player_accounts(v_player);
  perform 1 from public.vaults where player_id = v_player for update;
  v_status := public.vault_status(v_player);
  v_amount := coalesce((v_status ->> 'accrued_cents')::bigint, 0);
  if v_amount < greatest(1, public.config_bigint('economy', '{vaultMinClaimCents}', 100)) then
    perform public.api_error('nothing_to_claim');
  end if;

  v_tx := public.ledger_transfer(
    public.ledger_system_account('mint'), public.ledger_player_account(v_player, 'player_cash'),
    v_amount, 'vault_claim', 'Grundeinkommen aus dem Tresor', 'vault', null,
    'vault:' || v_player::text || ':' || p_request_id::text, v_player);

  select greatest(0, floor(extract(epoch from (v_now - v.accrual_started_at))))::integer into v_total
    from public.vaults v where v.player_id = v_player;
  v_counted := (v_status ->> 'accrued_seconds')::integer;
  insert into public.vault_claims (player_id, request_id, amount_cents, accrued_seconds, forfeited_seconds, ledger_transaction_id)
  values (v_player, p_request_id, v_amount, v_counted, greatest(0, v_total - v_counted), v_tx)
  on conflict (player_id, request_id) do nothing;
  update public.vaults
     set accrual_started_at = v_now, last_claimed_at = v_now,
         total_claimed_cents = total_claimed_cents + v_amount, full_notified_at = null
   where player_id = v_player;

  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'claimed_cents', v_amount,
    'cash_cents',    (select a.balance_cents from public.ledger_accounts a where a.owner_player_id = v_player and a.kind = 'player_cash'),
    'full_at',       v_now + make_interval(secs => v_hours * 3600)));
end;
$$;

create or replace function public.complete_tutorial(p_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_done   timestamptz;
  v_xp     integer := 0;
  v_prof   public.profiles;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'complete_tutorial');
  if v_replay is not null then
    return v_replay;
  end if;
  select pp.tutorial_completed_at into v_done from public.player_private pp where pp.player_id = v_player for update;
  if v_done is null then
    update public.player_private set tutorial_completed_at = now() where player_id = v_player;
    v_xp := public.grant_xp(v_player, 'tutorial',
              public.config_double('progression', '{xpSources,tutorial,xp}', 50)::integer, 'tutorial', 'tutorial', null);
  end if;
  select * into v_prof from public.profiles where id = v_player;
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'xp_awarded', v_xp, 'level', v_prof.level, 'xp_total', v_prof.xp_total,
    'already_completed', v_done is not null));
end;
$$;

-- ---------------------------------------------------------------------------
-- Privileges
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.security_depth(uuid, boolean)', 'public.execute_fill(uuid, bigint, bigint, boolean, boolean)',
    'public.cancel_order_internal(uuid)', 'public.lock_player_accounts(uuid)', 'public.vault_status(uuid)',
    'public.place_order(uuid, text, text, text, bigint, bigint)', 'public.cancel_order(uuid, uuid)',
    'public.claim_vault(uuid)', 'public.complete_tutorial(uuid)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  grant execute on function public.place_order(uuid, text, text, text, bigint, bigint) to authenticated;
  grant execute on function public.cancel_order(uuid, uuid) to authenticated;
  grant execute on function public.claim_vault(uuid) to authenticated;
  grant execute on function public.complete_tutorial(uuid) to authenticated;
end;
$$;
-- ===== idempotent copy of migrations/20261111000300_m1_market_tick.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · M1 · 0300 · Market tick in PL/pgSQL (replaces the edge-function
--                    runner of ADR-004 for the alpha)
-- =============================================================================
-- public.market_tick() runs every 5 seconds via pg_cron. It is a port of
-- stepMarketTick() in src/lib/sim/tick.ts (docs/SIMULATION.md section 3):
--   1. fill resting limit orders that the current quote makes marketable
--   2. per stock: sentiment decay, player flow -> market maker inventory,
--      pressure of value fund (anchor to fair value), momentum traders,
--      retail herd and market-maker hedging, linear price impact, noise per
--      size class x sector, circuit breaker, stochastic rounding, EMAs, quote
--   3. per bond: price from the yield (policy rate + maturity spread) as
--      present value, plus a small mean-reverting deviation and player flow
--   4. NEXA 30 = sum(shares x price) / divisor
--   5. quotes (day high/low/volume/change, roll at the 22:00 bell),
--      price_ticks, candles 1m/5m/1h/1q/1y, runtime and tick log
-- Pension and index funds of the TS model start at their target holding and
-- the policy rate is constant in M1, so their pressure is zero and they are
-- left out here (placeholders, ROADMAP M1).
-- Ticks never overlap: transaction-level advisory lock 7311001 (try-lock).
-- =============================================================================

-- Yield of a bond for a remaining maturity (bondYieldBps in src/lib/sim/bonds.ts).
create or replace function public.bond_yield_bps(p_policy_rate_bps integer, p_years double precision, p_bonds jsonb)
returns integer
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_spread double precision;
  v_lo     record;
  v_hi     record;
  v_raw    double precision;
begin
  -- maturities sorted by years; interpolate the spread linearly
  select (m ->> 'years')::double precision as years, (m ->> 'spreadBps')::double precision as spread
    into v_lo
    from jsonb_array_elements(coalesce(p_bonds -> 'maturities', '[]'::jsonb)) m
   where (m ->> 'years')::double precision <= p_years
   order by 1 desc limit 1;
  select (m ->> 'years')::double precision as years, (m ->> 'spreadBps')::double precision as spread
    into v_hi
    from jsonb_array_elements(coalesce(p_bonds -> 'maturities', '[]'::jsonb)) m
   where (m ->> 'years')::double precision >= p_years
   order by 1 asc limit 1;
  if v_lo.years is null and v_hi.years is null then
    v_spread := 0;
  elsif v_lo.years is null then
    v_spread := v_hi.spread;
  elsif v_hi.years is null or v_hi.years = v_lo.years then
    v_spread := v_lo.spread;
  else
    v_spread := v_lo.spread + (p_years - v_lo.years) / (v_hi.years - v_lo.years) * (v_hi.spread - v_lo.spread);
  end if;
  v_raw := p_policy_rate_bps + v_spread;
  return round(least(public.cfg_num(p_bonds, '{maxYieldBps}', 400),
                     greatest(public.cfg_num(p_bonds, '{minYieldBps}', 200), v_raw)))::integer;
end;
$$;

-- Clean price as a fraction of face value (1.0 = par): present value of the
-- remaining coupons and the redemption minus accrued interest. p_periods is
-- the remaining maturity in coupon periods (may be fractional).
create or replace function public.bond_clean_price(
  p_coupon_bps integer, p_yield_bps double precision, p_periods double precision, p_per_year double precision
)
returns double precision
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_c     double precision := p_coupon_bps / 10000.0 / p_per_year;
  v_y     double precision := p_yield_bps / 10000.0 / p_per_year;
  v_n     integer;
  v_dirty double precision := 0;
  k       integer;
begin
  if p_periods <= 0 then
    return 1;
  end if;
  v_n := ceil(p_periods)::integer;
  for k in 1..v_n loop
    v_dirty := v_dirty + v_c / power(1 + v_y, p_periods - v_n + k);
  end loop;
  v_dirty := v_dirty + 1 / power(1 + v_y, p_periods);
  return v_dirty - v_c * (v_n - p_periods);
end;
$$;

-- Fills resting limit orders that are marketable against the current quote
-- (buy: ask <= limit, sell: bid >= limit) at their limit price.
create or replace function public.fill_resting_orders()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_players uuid[];
  v_n       integer := 0;
  r         record;
  o         public.orders;
begin
  select array_agg(distinct o2.player_id) into v_players
    from public.orders o2
    join public.security_quotes q on q.security_id = o2.security_id
    join public.securities s on s.id = o2.security_id
   where o2.type = 'limit' and o2.status in ('open', 'partially_filled')
     and s.status = 'listed' and s.is_tradable
     and ((o2.side = 'buy' and q.ask_e4 <= o2.limit_price_e4) or (o2.side = 'sell' and q.bid_e4 >= o2.limit_price_e4));
  if v_players is null then
    return 0;
  end if;

  -- lock every affected player's accounts up front, in id order (deadlock free)
  perform 1 from public.ledger_accounts a where a.owner_player_id = any (v_players) order by a.id for update;

  for r in
    select o2.id
      from public.orders o2
      join public.security_quotes q on q.security_id = o2.security_id
      join public.securities s on s.id = o2.security_id
     where o2.type = 'limit' and o2.status in ('open', 'partially_filled')
       and s.status = 'listed' and s.is_tradable
       and ((o2.side = 'buy' and q.ask_e4 <= o2.limit_price_e4) or (o2.side = 'sell' and q.bid_e4 >= o2.limit_price_e4))
     order by o2.created_at, o2.id
  loop
    begin
      select * into o from public.orders where id = r.id for update;
      if o.status in ('open', 'partially_filled') and o.quantity > o.filled_quantity then
        perform public.execute_fill(o.id, o.quantity - o.filled_quantity, o.limit_price_e4, true, false);
        v_n := v_n + 1;
      end if;
    exception when others then
      raise warning 'NEXA: resting order % not filled: % (%)', r.id, sqlerrm, sqlstate;
    end;
  end loop;
  return v_n;
end;
$$;

-- ---------------------------------------------------------------------------
-- The tick. p_now is the simulated time (tests); market_tick() uses game_now().
-- ---------------------------------------------------------------------------
create or replace function public.market_tick_at(p_now timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_started   timestamptz := clock_timestamp();
  rt          public.sim_runtime;
  v_seq       bigint;
  v_time      jsonb := coalesce(public.config_jsonb('time'), '{}'::jsonb);
  v_trading   jsonb := coalesce(public.config_jsonb('trading'), '{}'::jsonb);
  v_ai        jsonb := coalesce(public.config_jsonb('aiInvestors'), '{}'::jsonb);
  v_sectors   jsonb := coalesce(public.config_jsonb('sectors'), '{}'::jsonb);
  v_bonds     jsonb := coalesce(public.config_jsonb('bonds'), '{}'::jsonb);
  v_regular   boolean;
  v_bell      timestamptz;
  v_qstart    timestamptz;
  v_ystart    timestamptz;
  v_new_day   boolean;
  v_filled    integer;
  v_policy    integer;
  v_epoch     constant timestamptz := '2000-01-01 00:00:00+00';
  v_local     timestamp := p_now at time zone 'Europe/Berlin';
  v_open_h    double precision;
  v_close_h   double precision;
  -- config scalars
  c_liq       double precision;
  c_noise     double precision;
  c_spreadf   double precision;
  c_depthfrac double precision;
  c_impact    double precision;
  c_exp       double precision;
  c_imm       double precision;
  c_hedge     double precision;
  c_maxret    double precision;
  c_minprice  bigint;
  c_minhalf   bigint;
  c_widen     double precision;
  c_decay     double precision;
  c_emaf      double precision;
  c_emas      double precision;
  c_vf_cap    double precision;
  c_vf_gap    double precision;
  c_vf_dead   double precision;
  c_mo_cap    double precision;
  c_mo_ts     double precision;
  c_rh_cap    double precision;
  c_rh_chase  double precision;
  c_rh_ts     double precision;
  c_mm_speed  double precision;
  c_basevol   double precision;
  c_nscale    double precision;
  c_qpy       double precision;
  c_qsec      double precision;
  -- per security
  r           record;
  v_price     double precision;
  v_depth     double precision;
  v_sent      double precision;
  v_flow      double precision;
  v_mm        double precision;
  v_ef        double precision;
  v_es        double precision;
  v_gap       double precision;
  v_trend     double precision;
  v_pv        double precision;
  v_pm        double precision;
  v_pr        double precision;
  v_pmm       double precision;
  v_ret       double precision;
  v_sigma     double precision;
  v_exact     double precision;
  v_new       bigint;
  v_half_bps  double precision;
  v_half      bigint;
  v_bid       bigint;
  v_ask       bigint;
  v_vol       bigint;
  v_dev       double precision;
  v_periods   double precision;
  v_years     double precision;
  v_yield     double precision;
  v_yield_out integer;
  v_mcap      bigint;
  v_imp_flow  double precision;
  -- bulk arrays
  a_id   uuid[] := '{}';
  a_p    bigint[] := '{}';
  a_b    bigint[] := '{}';
  a_a    bigint[] := '{}';
  a_v    bigint[] := '{}';
  a_s    double precision[] := '{}';
  a_ef   double precision[] := '{}';
  a_es   double precision[] := '{}';
  a_mm   double precision[] := '{}';
  a_dev  double precision[] := '{}';
  a_flow bigint[] := '{}';
  a_y    integer[] := '{}';
  a_mc   bigint[] := '{}';
  -- index
  ix     record;
  v_cap  numeric;
  v_ixv  bigint;
  v_n    integer := 0;
begin
  if not pg_try_advisory_xact_lock(7311001) then
    return jsonb_build_object('skipped', 'busy');
  end if;
  select * into rt from public.sim_runtime where id;
  if rt.is_paused then
    return jsonb_build_object('skipped', 'paused', 'tick_seq', rt.tick_seq);
  end if;
  v_seq := rt.tick_seq + 1;

  -- session and calendar ----------------------------------------------------
  v_open_h  := public.cfg_num(v_time, '{marketOpenHour}', 8);
  v_close_h := public.cfg_num(v_time, '{marketCloseHour}', 22);
  v_regular := (extract(hour from v_local) + extract(minute from v_local) / 60.0) >= v_open_h
           and (extract(hour from v_local) + extract(minute from v_local) / 60.0) < v_close_h;
  v_bell    := public.trading_day_start(p_now);
  v_qstart  := public.quarter_bucket_start(p_now);
  v_ystart  := public.game_year_bucket_start(p_now);
  v_new_day := coalesce((rt.state ->> 'day_start')::timestamptz, '-infinity'::timestamptz) < v_bell;
  select cb.policy_rate_bps into v_policy from public.central_bank_state cb where cb.id;
  v_policy := coalesce(v_policy, public.config_double('centralBank', '{startRateBps}', 300)::integer);

  -- config ----------------------------------------------------------------------
  c_liq       := case when v_regular then 1 else public.cfg_num(v_time, '{afterHours,liquidityMultiplier}', 0.25) end;
  c_noise     := case when v_regular then 1 else public.cfg_num(v_time, '{afterHours,volatilityMultiplier}', 0.5) end;
  c_spreadf   := case when v_regular then 1 else public.cfg_num(v_time, '{afterHours,spreadMultiplier}', 3) end;
  c_depthfrac := public.cfg_num(v_trading, '{priceImpact,depthFreeFloatFraction}', 0.002);
  c_impact    := public.cfg_num(v_trading, '{priceImpact,impactBpsPerDepth}', 100) / 10000.0;
  c_exp       := public.cfg_num(v_trading, '{priceImpact,exponent}', 1);
  c_imm       := public.cfg_num(v_trading, '{priceImpact,immediateShare}', 0.5);
  c_hedge     := public.cfg_num(v_trading, '{priceImpact,marketMakerHedgeShare}', 0.5);
  c_maxret    := public.cfg_num(v_trading, '{maxTickReturnBps}', 300) / 10000.0;
  c_minprice  := greatest(1, public.cfg_num(v_trading, '{minPriceE4}', 1))::bigint;
  c_minhalf   := greatest(1, public.cfg_num(v_trading, '{spread,minHalfSpreadE4}', 1))::bigint;
  c_widen     := public.cfg_num(v_trading, '{spread,sentimentWideningBps}', 20);
  c_decay     := public.cfg_num(v_ai, '{sentimentDecayPerTick}', 0.0019);
  c_emaf      := public.cfg_num(v_ai, '{emaFastAlpha}', 0.15);
  c_emas      := public.cfg_num(v_ai, '{emaSlowAlpha}', 0.0165);
  c_vf_cap    := public.cfg_num(v_ai, '{archetypes,value_fund,capitalShare}', 0.3)
               * public.cfg_num(v_ai, '{archetypes,value_fund,reactionSpeed}', 0.000167) * c_liq;
  c_vf_gap    := public.cfg_num(v_ai, '{archetypes,value_fund,params,gapScale}', 0.5);
  c_vf_dead   := public.cfg_num(v_ai, '{archetypes,value_fund,params,deadBand}', 0.01);
  c_mo_cap    := public.cfg_num(v_ai, '{archetypes,momentum_trader,capitalShare}', 0.1)
               * public.cfg_num(v_ai, '{archetypes,momentum_trader,reactionSpeed}', 0.0002) * c_liq;
  c_mo_ts     := public.cfg_num(v_ai, '{archetypes,momentum_trader,params,trendScale}', 0.02);
  c_rh_cap    := public.cfg_num(v_ai, '{archetypes,retail_herd,capitalShare}', 0.1)
               * public.cfg_num(v_ai, '{archetypes,retail_herd,reactionSpeed}', 0.0012) * c_liq;
  c_rh_chase  := public.cfg_num(v_ai, '{archetypes,retail_herd,params,chaseGain}', 0.1);
  c_rh_ts     := public.cfg_num(v_ai, '{archetypes,retail_herd,params,trendScale}', 0.02);
  c_mm_speed  := public.cfg_num(v_ai, '{archetypes,market_maker,reactionSpeed}', 0.005) * c_liq;
  c_basevol   := public.cfg_num(v_ai, '{baselineVolumeDepthFraction}', 0.02);
  -- Scale on tickNoiseBps for stocks. The TS values give daily ranges of about
  -- 10 % (blue chips) to 90 % (penny stocks); 0.2 brings them to the M1 target
  -- (1-4 %, 3-8 %, 10-30 %). Fallback until balance.ts has aiInvestors.tickNoiseScale.
  c_nscale    := public.cfg_num(v_ai, '{tickNoiseScale}', 0.2);
  c_qpy       := greatest(1, public.cfg_num(v_bonds, '{couponsPerGameYear}', 4));
  c_qsec      := public.cfg_num(v_time, '{quarterHours}', 6) * 3600;

  -- 1. resting limit orders against the quote players currently see ----------
  v_filled := public.fill_resting_orders();

  -- 2./3. stocks and bonds ---------------------------------------------------------
  for r in
    select s.id, s.kind, s.sector_key, c.tier::text as tier, c.shares_outstanding,
           q.last_price_e4,
           st.fair_value_e4, st.sentiment, st.ema_fast, st.ema_slow, st.maker_inventory,
           st.pending_player_flow, st.price_deviation, st.volatility, st.liquidity_shares, st.spread_bps,
           b.coupon_bps, b.matures_at, b.face_value_cents
      from public.securities s
      join public.security_quotes q on q.security_id = s.id
      join public.security_sim_state st on st.security_id = s.id
      left join public.companies c on c.id = s.company_id
      left join public.bonds b on b.security_id = s.id
     where s.status = 'listed' and s.kind in ('stock', 'bond')
  loop
    v_price := r.last_price_e4;
    v_flow  := r.pending_player_flow;
    v_sent  := greatest(-1, least(1, coalesce(r.sentiment, 0) * (1 - c_decay)));
    v_ef    := coalesce(r.ema_fast, v_price);
    v_es    := coalesce(r.ema_slow, v_price);
    v_mm    := coalesce(r.maker_inventory, 0) - v_flow;
    v_dev   := coalesce(r.price_deviation, 0);
    v_yield_out := null;
    v_mcap  := null;

    if r.kind = 'stock' and r.shares_outstanding is not null then
      v_depth := greatest(1, r.shares_outstanding * c_depthfrac * c_liq);
      -- value fund: anchor to the fair value outside the dead band
      v_gap := ln(r.fair_value_e4 / v_price);
      if abs(v_gap) <= c_vf_dead then
        v_pv := 0;
      else
        v_pv := r.shares_outstanding * c_vf_cap
              * greatest(-1, least(1, (v_gap - sign(v_gap) * c_vf_dead) / c_vf_gap));
      end if;
      v_trend := case when v_es > 0 then v_ef / v_es - 1 else 0 end;
      v_pm  := r.shares_outstanding * c_mo_cap * tanh(v_trend / c_mo_ts);
      v_pr  := r.shares_outstanding * c_rh_cap * greatest(-1, least(1, v_sent + c_rh_chase * tanh(v_trend / c_rh_ts)));
      v_pmm := -v_mm * c_mm_speed * c_hedge;
      v_ret := sign(v_pv + v_pm + v_pr + v_pmm) * c_impact * power(abs(v_pv + v_pm + v_pr + v_pmm) / v_depth, c_exp)
             + c_imm * sign(v_flow) * c_impact * power(abs(v_flow) / v_depth, c_exp);
      v_sigma := public.cfg_num(v_ai, array['tickNoiseBps', coalesce(r.tier, 'midcap')], 15) / 10000.0
               * public.cfg_num(v_sectors, array[coalesce(r.sector_key, ''), 'volatilityMultiplier'], 1)
               * c_noise * c_nscale;
      v_ret := greatest(-c_maxret, least(c_maxret, v_ret + v_sigma * public.gauss_random()));
      v_exact := v_price * exp(v_ret);
      v_new := floor(v_exact)::bigint + case when random() < v_exact - floor(v_exact) then 1 else 0 end;
      v_new := greatest(c_minprice, v_new);
      v_mm  := v_mm * (1 - c_mm_speed);
      v_half_bps := (public.cfg_num(v_trading, array['spread', 'halfSpreadBps', coalesce(r.tier, 'midcap')], 15)
                     + c_widen * least(1, abs(v_sent))) * c_spreadf;
      v_vol := round(abs(v_pv) + abs(v_pm) + abs(v_pr) + abs(v_pmm) + v_depth * c_basevol * (0.5 + random()))::bigint;
      v_mcap := public.div_round_half_even(r.shares_outstanding::numeric * v_new, 100);
    elsif r.kind = 'bond' and r.matures_at is not null then
      v_depth   := greatest(1, coalesce(r.liquidity_shares, 100000) * c_liq);
      v_periods := extract(epoch from (r.matures_at - p_now)) / c_qsec;
      v_years   := greatest(v_periods / c_qpy, 0);
      v_yield   := public.bond_yield_bps(v_policy, v_years, v_bonds);
      v_imp_flow := c_imm * sign(v_flow) * c_impact * power(abs(v_flow) / v_depth, c_exp);
      v_dev := v_dev * (1 - c_decay) + coalesce(r.volatility, 0) * c_noise * public.gauss_random() + v_imp_flow;
      if v_periods > 0 then
        v_new := greatest(c_minprice, round(public.bond_clean_price(r.coupon_bps, v_yield, v_periods, c_qpy)
                                            * exp(v_dev) * r.face_value_cents * 100)::bigint);
        v_yield_out := round(v_yield - v_dev * 10000 / greatest(v_years, 0.25))::integer;
      else
        v_new := r.face_value_cents * 100;
        v_yield_out := 0;
      end if;
      v_half_bps := coalesce(r.spread_bps, 10) / 2.0 * c_spreadf;
      v_vol := round(v_depth * c_basevol * (0.5 + random()))::bigint;
    else
      continue;
    end if;

    v_ef := v_ef + c_emaf * (v_new - v_ef);
    v_es := v_es + c_emas * (v_new - v_es);
    v_half := greatest(c_minhalf, round(v_new * v_half_bps / 10000.0)::bigint);
    v_bid := greatest(c_minprice, v_new - v_half);
    v_ask := v_new + v_half;
    if v_ask <= v_bid then
      v_ask := v_bid + 1;
    end if;

    a_id := a_id || r.id;      a_p := a_p || v_new;        a_b := a_b || v_bid;     a_a := a_a || v_ask;
    a_v := a_v || v_vol;       a_s := a_s || v_sent;       a_ef := a_ef || v_ef;    a_es := a_es || v_es;
    a_mm := a_mm || v_mm;      a_dev := a_dev || v_dev;    a_flow := a_flow || r.pending_player_flow;
    a_y := a_y || v_yield_out; a_mc := a_mc || v_mcap;
    v_n := v_n + 1;
  end loop;

  update public.security_sim_state st
     set sentiment = u.s, ema_fast = u.ef, ema_slow = u.es, maker_inventory = u.mm,
         price_deviation = u.dev, pending_player_flow = st.pending_player_flow - u.flow
    from unnest(a_id, a_s, a_ef, a_es, a_mm, a_dev, a_flow) as u(id, s, ef, es, mm, dev, flow)
   where st.security_id = u.id;

  update public.security_quotes q
     set last_price_e4 = u.p,
         bid_e4 = u.b,
         ask_e4 = u.a,
         prev_close_e4 = case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end,
         day_open_e4 = case when v_new_day then u.p else coalesce(q.day_open_e4, u.p) end,
         day_high_e4 = case when v_new_day then u.p else greatest(coalesce(q.day_high_e4, u.p), u.p) end,
         day_low_e4 = case when v_new_day then u.p else least(coalesce(q.day_low_e4, u.p), u.p) end,
         day_volume = case when v_new_day then u.v else q.day_volume + u.v end,
         day_turnover_cents = case when v_new_day then 0 else q.day_turnover_cents end,
         change_bps = greatest(-1000000, least(1000000, round(
                        (u.p - case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end) * 10000.0
                        / greatest(1, case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end))))::integer,
         market_cap_cents = coalesce(u.mc, q.market_cap_cents),
         yield_bps = coalesce(u.y, q.yield_bps),
         tick_seq = v_seq,
         updated_at = p_now
    from unnest(a_id, a_p, a_b, a_a, a_v, a_y, a_mc) as u(id, p, b, a, v, y, mc)
   where q.security_id = u.id;

  -- 4. indices ---------------------------------------------------------------------
  for ix in
    select i.security_id, i.divisor
      from public.indices i join public.securities s on s.id = i.security_id
     where s.status = 'listed'
  loop
    select sum(c.shares_outstanding::numeric * q.last_price_e4) / 100
      into v_cap
      from public.index_memberships m
      join public.securities s on s.id = m.member_security_id
      join public.companies c on c.id = s.company_id
      join public.security_quotes q on q.security_id = s.id
     where m.index_security_id = ix.security_id and m.left_at is null;
    if v_cap is null or ix.divisor <= 0 then
      continue;
    end if;
    v_ixv := greatest(1, round(v_cap / ix.divisor::numeric))::bigint;
    update public.security_quotes q
       set last_price_e4 = v_ixv,
           prev_close_e4 = case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end,
           day_open_e4 = case when v_new_day then v_ixv else coalesce(q.day_open_e4, v_ixv) end,
           day_high_e4 = case when v_new_day then v_ixv else greatest(coalesce(q.day_high_e4, v_ixv), v_ixv) end,
           day_low_e4 = case when v_new_day then v_ixv else least(coalesce(q.day_low_e4, v_ixv), v_ixv) end,
           change_bps = round((v_ixv - case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end) * 10000.0
                        / greatest(1, case when v_new_day then q.last_price_e4 else coalesce(q.prev_close_e4, q.last_price_e4) end))::integer,
           market_cap_cents = round(v_cap)::bigint,
           tick_seq = v_seq,
           updated_at = p_now
     where q.security_id = ix.security_id;
    a_id := a_id || ix.security_id;
    a_p  := a_p || v_ixv;
    a_v  := a_v || 0::bigint;
  end loop;

  -- 5. ticks and candles --------------------------------------------------------------
  insert into public.price_ticks (security_id, ts, tick_seq, price_e4, volume)
  select u.id, p_now, v_seq, u.p, u.v from unnest(a_id, a_p, a_v) as u(id, p, v)
  on conflict do nothing;

  insert into public.candles as c (security_id, interval, bucket_start, open_e4, high_e4, low_e4, close_e4, volume, tick_count)
  select u.id, iv.i, iv.b, u.p, u.p, u.p, u.p, u.v, 1
    from unnest(a_id, a_p, a_v) as u(id, p, v)
   cross join (values
     ('1m'::public.candle_interval, date_bin('1 minute', p_now, v_epoch)),
     ('5m'::public.candle_interval, date_bin('5 minutes', p_now, v_epoch)),
     ('1h'::public.candle_interval, date_bin('1 hour', p_now, v_epoch)),
     ('1q'::public.candle_interval, v_qstart),
     ('1y'::public.candle_interval, v_ystart)) as iv(i, b)
  on conflict (security_id, interval, bucket_start) do update
     set high_e4 = greatest(c.high_e4, excluded.high_e4),
         low_e4 = least(c.low_e4, excluded.low_e4),
         close_e4 = excluded.close_e4,
         volume = c.volume + excluded.volume,
         tick_count = c.tick_count + 1;

  -- runtime, public market status, tick log
  update public.sim_runtime
     set tick_seq = v_seq, last_tick_at = p_now,
         state = case when v_new_day then state || jsonb_build_object('day_start', v_bell) else state end
   where id;
  update public.market_status
     set phase = case when v_regular then 'open'::public.market_phase else 'after_hours'::public.market_phase end,
         phase_changed_at = case when phase is distinct from (case when v_regular then 'open'::public.market_phase
                                                                   else 'after_hours'::public.market_phase end)
                                 then p_now else phase_changed_at end,
         next_open_at = case when v_local < v_local::date + make_interval(secs => v_open_h * 3600)
                             then (v_local::date + make_interval(secs => v_open_h * 3600)) at time zone 'Europe/Berlin'
                             else (v_local::date + 1 + make_interval(secs => v_open_h * 3600)) at time zone 'Europe/Berlin' end,
         next_close_at = case when v_local < v_local::date + make_interval(secs => v_close_h * 3600)
                              then (v_local::date + make_interval(secs => v_close_h * 3600)) at time zone 'Europe/Berlin'
                              else (v_local::date + 1 + make_interval(secs => v_close_h * 3600)) at time zone 'Europe/Berlin' end,
         tick_seq = v_seq, last_tick_at = p_now, is_halted = false, halt_reason = null
   where id;
  insert into public.sim_tick_log (tick_seq, started_at, duration_ms, securities_updated, orders_filled)
  values (v_seq, v_started, round(extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer, v_n, v_filled)
  on conflict (tick_seq) do nothing;

  return jsonb_build_object(
    'tick_seq', v_seq, 'session', case when v_regular then 'regular' else 'after_hours' end,
    'securities', v_n, 'orders_filled', v_filled, 'new_day', v_new_day,
    'duration_ms', round(extract(epoch from (clock_timestamp() - v_started)) * 1000, 2));
end;
$$;
comment on function public.market_tick_at(timestamptz) is 'Internal: one market tick at the given (simulated) time. Port of stepMarketTick() (src/lib/sim/tick.ts).';

create or replace function public.market_tick()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  return public.market_tick_at(public.game_now());
end;
$$;
comment on function public.market_tick() is 'pg_cron every 5 seconds: one market tick at game_now(). Skips while paused or while another tick holds the lock.';

do $$
declare
  f text;
begin
  foreach f in array array[
    'public.bond_yield_bps(integer, double precision, jsonb)',
    'public.bond_clean_price(integer, double precision, double precision, double precision)',
    'public.fill_resting_orders()', 'public.market_tick_at(timestamptz)', 'public.market_tick()'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end;
$$;
